// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.parallel.ResourceLock;
import org.junit.jupiter.api.parallel.Resources;

@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeStrategyProposalTest {

	private String previousStartupCost;

	@BeforeEach
	void isolateDefaultStartupCost() {
		previousStartupCost = System.clearProperty(LmdbNativeWork.PARALLEL_STARTUP_COST_PROPERTY);
	}

	@AfterEach
	void restoreStartupCost() {
		if (previousStartupCost == null) {
			System.clearProperty(LmdbNativeWork.PARALLEL_STARTUP_COST_PROPERTY);
		} else {
			System.setProperty(LmdbNativeWork.PARALLEL_STARTUP_COST_PROPERTY, previousStartupCost);
		}
	}

	@Test
	void eightWorkerParallelProposalBeatsBatchForMillionRowOverlap() {
		double batch = LmdbNativeWork.batchCost(1_000_000D, 1_000_000D);
		double parallel = LmdbNativeWork.parallelCost(2_000_000D, 8);

		assertThat(batch).isEqualTo(2_000_000D);
		assertThat(parallel).isEqualTo(262_500D);
	}

	@Test
	void oneWorkerParallelProposalLosesToBatchForSameOverlap() {
		double batch = LmdbNativeWork.batchCost(1_000_000D, 1_000_000D);
		double parallel = LmdbNativeWork.parallelCost(2_000_000D, 1);

		assertThat(parallel).isEqualTo(2_012_500D);
	}

	@Test
	void anUnusedProposalReleasesItsAdmissionExactlyOnce() {
		AtomicInteger releases = new AtomicInteger();
		LmdbNativeStrategyProposal<String> proposal = new LmdbNativeStrategyProposal<>(() -> "unused", 1D,
				"unused", releases::incrementAndGet);

		proposal.close();
		proposal.close();

		assertThat(releases).hasValue(1);
	}

	@Test
	void anOpenedProposalTransfersCleanupToItsResultAndCannotReopen() throws Exception {
		AtomicInteger opens = new AtomicInteger();
		AtomicInteger unusedReleases = new AtomicInteger();
		LmdbNativeStrategyProposal<String> proposal = new LmdbNativeStrategyProposal<>(() -> {
			opens.incrementAndGet();
			return "selected";
		}, 1D, "selected", unusedReleases::incrementAndGet);

		assertThat(proposal.open()).isEqualTo("selected");
		assertThatThrownBy(proposal::open).isInstanceOf(IllegalStateException.class);
		proposal.close();

		assertThat(opens).hasValue(1);
		assertThat(unusedReleases).hasValue(0);
	}
}
